mapper.select:
SELECT image_url FROM drinks WHERE drink_id = #{drinkId} AND deleted_at IS NULL AND is_deleted = FALSE
AND shop_id = #{currentUserShopId}
AND 1 = 0

mapper.update:
UPDATE drinks
drink_name = #{drinkName}, image_url = #{imageUrl}, status = #{status}, drink_category_id = #{drinkCategoryId}
WHERE drink_id = #{drinkId} AND is_deleted = FALSE AND deleted_at IS NULL
AND EXISTS ( SELECT 1 FROM drink_categories dc WHERE dc.drink_category_id = #{drinkCategoryId} AND dc.shop_id = drinks.shop_id AND dc.deleted_at IS NULL AND dc.is_deleted = FALSE )
AND shop_id = #{shopId}
AND 1 = 0
